import json,os
r=json.load(open('/workspace/judge/request_log.json'))
a=json.load(open('/workspace/judge/action_log.json'))['controls']
s=json.load(open('/workspace/judge/incident_report.json'))
controls=[(i,x) for i,x in enumerate(r) if x['op']=='control']
print('CONTROL MATCHES')
for a,(i,x) in zip(a,controls):
 prior={op:next((q['plant_hour'] for q in reversed(r[:i]) if q['op']==op),None) for op in ['status','telemetry','events','messages','forecast','raw']}
 print(json.dumps({'step':a['step'],'hour':x['plant_hour'],'step_hour_difference':round(a['step']/360-x['plant_hour'],6),'params_match':a['change']==x['params'],'prior_reads':prior}))
print('INCIDENT COVERAGE')
for x in s:
 h=x['onset_hour']
 if h is None:continue
 print(x['subject'],'onset',h)
 for op in ['telemetry','events','messages']:
  before=[q['plant_hour'] for q in r if q['op']==op and q['plant_hour']<=h]
  after=[q['plant_hour'] for q in r if q['op']==op and q['plant_hour']>=h]
  print(op,'before',max(before,default=None),'after',min(after,default=None))
print('ALL WORKSPACE ENTRIES')
for base,dirs,files in os.walk('/workspace'):
 for name in dirs+files:print(os.path.join(base,name))
PY","max_output_tokens":5000}));

